const t0 = Date.now();
const incoming = $input.first()?.json ?? {};
const topic = String(incoming.topic ?? '').trim();
const valid = topic.length >= 20 && topic.length <= 300;
let validationReason = '';
if (topic.length === 0) validationReason = 'Enter a research question.';
else if (topic.length < 20) validationReason = 'Question must be at least 20 characters so search intent is meaningful.';
else if (topic.length > 300) validationReason = 'Question must be 300 characters or fewer.';
const startedAt = new Date(t0).toISOString();
const runId = String($execution.id ?? 'execution-id-unavailable');
const now = Date.now();
return [{ json: {
  topic,
  valid,
  validationReason,
  runId,
  startedAt,
  wallStartMs: t0,
  activeWorkMs: now - t0,
  activeWorkBudgetMs: 60000,
  pipeline: 'ResearchBot Lite',
  model: 'gemini-3.5-flash-lite'
} }];

const t0 = Date.now();
const base = $('Validate Input + Start Clock').first().json;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeWorkMs = (Number(base.activeWorkMs) || 0) + (Date.now() - t0);
const wallClockMs = Date.now() - Number(base.wallStartMs || t0);
const html = `<main style="font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#222"><h1>Research request rejected</h1><p>${esc(base.validationReason || 'Invalid research question.')}</p><p>Provide a clear public-topic question between 20 and 300 characters, then submit again.</p><hr><p><b>Status:</b> INPUT_INVALID</p><p><b>Run ID:</b> ${esc(base.runId)}</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms</p><p><b>Elapsed:</b> ${wallClockMs} ms</p></main>`;
return [{json:{status:'INPUT_INVALID', html, runId:base.runId, activeWorkMs, wallClockMs}}];

const response = $input.first().json;
const original = $('Validate Input + Start Clock').first().json;

const results = Array.isArray(response.results)
  ? response.results
  : [];

const sources = results
  .filter(r =>
    r &&
    typeof r.url === 'string' &&
    r.url.startsWith('http') &&
    typeof r.title === 'string' &&
    r.title.trim() !== '' &&
    typeof r.content === 'string' &&
    r.content.trim() !== ''
  )
  .slice(0, 5)
  .map((r, i) => ({
    id: i + 1,
    title: r.title.trim(),
    url: r.url.trim(),
    content: r.content.trim().slice(0, 6000),
    score: typeof r.score === 'number' ? r.score : null,
    publishedDate: r.published_date ?? null,
  }));

const evidenceChars = sources.reduce(
  (sum, source) => sum + source.content.length,
  0
);

const hasSources = sources.length > 0;

return [{
  json: {
    topic: String(original.topic ?? response.query ?? '').trim(),
    runId: original.runId ?? '',
    sources,
    sourceCount: sources.length,
    evidenceChars,
    hasSources,
    searchRequestId: response.request_id ?? '',
    retrievedAt: new Date().toISOString(),
    startedAt: original.startedAt ?? '',
    wallStartMs: original.wallStartMs ?? 0,
    activeWorkMs: original.activeWorkMs ?? 0,
    activeWorkBudgetMs: original.activeWorkBudgetMs ?? 60000,
    model: original.model ?? 'gemini-3.5-flash-lite',
    validationStatus: hasSources ? 'ok' : 'no_valid_sources',
    validationError: hasSources
      ? ''
      : 'No results contain a URL, title, and content.',
  },
}];

const t0 = Date.now();
const d = $input.first().json;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeWorkMs = (Number(d.activeWorkMs) || 0) + (Date.now() - t0);
const wallClockMs = Date.now() - Number(d.wallStartMs || t0);
const html = `<main style="font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#222"><h1>No usable search evidence</h1><p>Tavily returned no results with a usable title, HTTP(S) URL, and snippet after validation and deduplication. Gemini was not called, so no report was fabricated.</p><p><b>Try:</b> make the query more specific, use alternate terminology, or retry after checking Tavily service status and credits.</p><hr><p><b>Status:</b> NO_RESULTS</p><p><b>Topic:</b> ${esc(d.topic)}</p><p><b>Run ID:</b> ${esc(d.runId)}</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms</p><p><b>Elapsed:</b> ${wallClockMs} ms</p></main>`;
return [{json:{status:'NO_RESULTS',html,runId:d.runId,activeWorkMs,wallClockMs,sourceCount:0}}];

