=
{{ JSON.stringify({
  systemInstruction: {
    parts: [{
      text: "You are a rigorous research analyst. Use only the supplied source evidence. Never invent facts or citations. Every finding must cite one or more supplied source IDs. If evidence is insufficient, state that clearly. Do not claim EV drivetrain efficiency exceeds 95% unless the evidence directly supports that claim."
    }]
  },
  contents: [{
    role: "user",
    parts: [{
      text:
        "Research topic: " + $json.topic +
        "\n\nSource evidence:\n" +
        JSON.stringify($json.sources) +
        "\n\nProduce a research report as a JSON object with title, executive_summary, findings, caveats, and conclusion. " +
        "Include 3 to 5 findings. Each finding must have claim (string), source_ids (array of source ID strings), and confidence (low, medium, or high). " +
        "Use only IDs from the supplied sources. Include caveats about evidence quality and missing information. Return JSON only."
    }]
  }],
  generationConfig: {
    temperature: 0.2,
    maxOutputTokens: 1600,
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        title: { type: "STRING" },
        executive_summary: { type: "STRING" },
        findings: {
          type: "ARRAY",
          items: {
            type: "OBJECT",
            properties: {
              claim: { type: "STRING" },
              source_ids: {
                type: "ARRAY",
                items: { type: "STRING" }
              },
              confidence: {
                type: "STRING",
                enum: ["low", "medium", "high"]
              }
            },
            required: ["claim", "source_ids", "confidence"]
          }
        },
        caveats: {
          type: "ARRAY",
          items: { type: "STRING" }
        },
        conclusion: { type: "STRING" }
      },
      required: [
        "title",
        "executive_summary",
        "findings",
        "caveats",
        "conclusion"
      ]
    }
  }
}) }}

