const t0 = Date.now();
const base = $('Normalize & Deduplicate Sources').first().json;
const response = $input.first()?.json ?? {};
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowed = new Map((Array.isArray(base.sources) ? base.sources : []).map(s => [String(s.id), s]));
const parts = response?.candidates?.[0]?.content?.parts;
const rawText = Array.isArray(parts) ? parts.map(p => typeof p?.text === 'string' ? p.text : '').filter(Boolean).join('\n').trim() : '';
const finishReason = String(response?.candidates?.[0]?.finishReason ?? '');
function finishFailure(message) {
  const end = Date.now();
  const activeWorkMs = (Number(base.activeWorkMs) || 0) + (end - t0);
  const wallClockMs = end - Number(base.wallStartMs || t0);
  const html = `<main style="font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#222"><h1>Report validation failed</h1><p>${esc(message)}</p><p>No report is marked complete. Retry the topic, then inspect the Gemini output in n8n execution history if this persists.</p><hr><p><b>Status:</b> MODEL_OUTPUT_INVALID</p><p><b>Run ID:</b> ${esc(base.runId)}</p><p><b>Sources retrieved:</b> ${esc(base.sourceCount)}</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms</p><p><b>Elapsed:</b> ${wallClockMs} ms</p></main>`;
  return [{json:{status:'MODEL_OUTPUT_INVALID',html,runId:base.runId,activeWorkMs,wallClockMs,sourceCount:base.sourceCount}}];
}
if (!rawText) return finishFailure('Gemini returned no usable text candidate (the output may have been blocked or unavailable).');
if (finishReason === 'MAX_TOKENS') return finishFailure('Gemini output reached its token limit and may be truncated. The workflow will not repair it with a second model call in this PoC.');
let candidate;
try {
  const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  candidate = JSON.parse(cleaned);
} catch {
  return finishFailure('Gemini output was not valid JSON, despite requesting structured output. No second synthesis call is made in this PoC.');
}
if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return finishFailure('Gemini output is not a JSON object.');
if (typeof candidate.title !== 'string' || !candidate.title.trim() || typeof candidate.executive_summary !== 'string' || !candidate.executive_summary.trim() || typeof candidate.conclusion !== 'string' || !candidate.conclusion.trim() || !Array.isArray(candidate.findings)) {
  return finishFailure('Gemini JSON omitted one or more required fields (title, executive_summary, findings, conclusion).');
}
// let needsReview = candidate.findings.length < 3 || candidate.findings.length > 5;
let needsReview = true;
const renderedFindings = candidate.findings.slice(0, 5).map((f, i) => {
  const claim = typeof f?.claim === 'string' ? f.claim.trim() : '';
  const rawIds = Array.isArray(f?.source_ids) ? f.source_ids : [];
  const knownIds = [];
  for (const rawId of rawIds) {
    const id = String(rawId ?? '').trim();
    if (allowed.has(id)) { if (!knownIds.includes(id)) knownIds.push(id); }
    else if (id) needsReview = true;
  }
  if (!claim || knownIds.length === 0) needsReview = true;
  const confidence = ['low','medium','high'].includes(String(f?.confidence).toLowerCase()) ? String(f.confidence).toLowerCase() : 'low';
  const links = knownIds.map(id => {
    const s = allowed.get(id);
    return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(id)}</a>`;
  }).join(', ');
  return `<li><p>${esc(claim || '(Finding text missing)')}</p><p><small><b>Confidence:</b> ${esc(confidence)}${links ? ` | <b>Sources:</b> ${links}` : ' | <b>Sources:</b> none validated'}</small></p></li>`;
});
const caveats = Array.isArray(candidate.caveats) ? candidate.caveats.filter(v => typeof v === 'string' && v.trim()).slice(0, 8) : [];
let unknownIdFound = false;
for (const f of candidate.findings) {
  const ids = Array.isArray(f?.source_ids) ? f.source_ids : [];
  if (ids.some(id => !allowed.has(String(id ?? '').trim()))) unknownIdFound = true;
}
if (unknownIdFound) needsReview = true;
const status = needsReview ? 'NEEDS_REVIEW' : 'COMPLETE';
// const sourceLinks = (base.sources || []).map(s => `<li id="${esc(s.id)}"><b>${esc(s.id)}.</b> <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>${s.publishedDate ? ` <small>(${esc(s.publishedDate)})</small>` : ''}<p><small>${esc(s.snippet)}</small></p></li>`).join('');
const sourceLinks = (base.sources || []).map(s =>
  `<li id="${esc(s.id)}"><b>${esc(s.id)}.</b> ` +
  `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>` +
  `${s.publishedDate ? ` <small>(${esc(s.publishedDate)})</small>` : ''}` +
  `<p><small>${esc(String(s.content ?? '').slice(0, 500))}</small></p></li>`
).join('');
const caveatBlock = caveats.length ? `<h2>Caveats</h2><ul>${caveats.map(c => `<li>${esc(c)}</li>`).join('')}</ul>` : '<h2>Caveats</h2><p>The model did not supply caveats. Source snippets may omit context; verify important claims at the original pages.</p>';
const reviewNotice = needsReview ? '<div style="border:1px solid #b45309;padding:.75rem;margin:1rem 0;background:#fffbeb"><b>Review required.</b> Citation IDs or finding count failed structural checks. Read source pages before relying on any claim.</div>' : '';
const end = Date.now();
const activeWorkMs = (Number(base.activeWorkMs) || 0) + (end - t0);
const wallClockMs = end - Number(base.wallStartMs || t0);
const html = `<main style="font-family:system-ui,sans-serif;line-height:1.55;max-width:1000px;margin:1rem auto;padding:1rem;color:#222"><header><p style="text-transform:uppercase;letter-spacing:.08em;font-size:.8rem;color:#555">ResearchBot Lite · ${esc(status)}</p><h1>${esc(candidate.title)}</h1><p><b>Research question:</b> ${esc(base.topic)}</p><p><small>Run ID: ${esc(base.runId)} | Generated: ${esc(new Date(end).toISOString())} | Sources: ${esc(base.sourceCount)} | Model: ${esc(base.model)}</small></p></header>${reviewNotice}<h2>Executive summary</h2><p>${esc(candidate.executive_summary)}</p><h2>Key findings</h2><ol>${renderedFindings.join('')}</ol>${caveatBlock}<h2>Conclusion</h2><p>${esc(candidate.conclusion)}</p><h2>Retrieved sources</h2><ol>${sourceLinks}</ol><aside style="border-top:1px solid #ddd;margin-top:1.5rem;padding-top:.75rem;color:#555"><p><b>Verification limit:</b> source IDs and links are checked against Tavily's returned results. This validates citation provenance structurally, not whether each page semantically proves its linked claim. Search snippets can omit context; inspect primary sources for consequential decisions.</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms. <b>Elapsed time:</b> ${wallClockMs} ms (includes external API latency and retries).</p><p>60-second active-work acceptance must be confirmed from n8n execution node timings; instrumented Code-node time is a subset of total successful non-HTTP node time.</p></aside></main>`;
return [{json:{status,html,runId:base.runId,activeWorkMs,wallClockMs,sourceCount:base.sourceCount,knownSourceIds:[...allowed.keys()],needsReview}}];

const t0 = Date.now();
const failed = $input.first()?.json ?? {};
const base = $('Validate Input + Start Clock').first().json;
const err = failed.error ?? failed;
const msg = typeof err === 'string' ? err : [err?.message, err?.description, err?.name, err?.httpCode, err?.statusCode].filter(Boolean).join(' ');
const s = String(msg || '').toLowerCase();
let code = 'SEARCH_UPSTREAM_ERROR';
let explanation = 'Tavily Search failed after automatic retries. Review the failed HTTP node in n8n execution details.';
let remedy = 'Check Tavily API status, credential selection, request details, and network connectivity.';
if (/401|unauthori[sz]|invalid.{0,12}(api )?key|credential/.test(s)) { code = 'TAVILY_AUTH_ERROR'; explanation = 'Tavily authentication failed.'; remedy = 'Edit the Tavily Header Auth credential: header name Authorization, value Bearer followed by your Tavily API token. Then run again.'; }
else if (/403|forbidden|permission/.test(s)) { code = 'TAVILY_FORBIDDEN'; explanation = 'Tavily rejected this request as forbidden.'; remedy = 'Check API account access and plan restrictions.'; }
else if (/429|quota|rate.?limit|too many requests|credits/.test(s)) { code = 'TAVILY_RATE_LIMIT'; explanation = 'Tavily rate/credit limit was reached. Short retries cannot reset an exhausted quota.'; remedy = 'Wait for the quota window to reset or inspect Tavily usage; then resubmit.'; }
else if (/timeout|timed out|etimedout|econnabort/.test(s)) { code = 'TAVILY_TIMEOUT'; explanation = 'Tavily did not respond before the request timeout.'; remedy = 'Check connectivity and provider status, then resubmit. Automatic transient retries have already been attempted.'; }
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeWorkMs = (Number(base.activeWorkMs) || 0) + (Date.now() - t0);
const wallClockMs = Date.now() - Number(base.wallStartMs || t0);
const html = `<main style="font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#222"><h1>Research could not start</h1><p>${esc(explanation)}</p><p>${esc(remedy)}</p><p>No report was generated; the workflow will not invent evidence.</p><hr><p><b>Status:</b> ${esc(code)}</p><p><b>Topic:</b> ${esc(base.topic)}</p><p><b>Run ID:</b> ${esc(base.runId)}</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms</p><p><b>Elapsed:</b> ${wallClockMs} ms</p></main>`;
return [{json:{status:code,html,runId:base.runId,activeWorkMs,wallClockMs}}];

const t0 = Date.now();
const failed = $input.first()?.json ?? {};
const base = $('Normalize & Deduplicate Sources').first().json;
const err = failed.error ?? failed;
const msg = typeof err === 'string' ? err : [err?.message, err?.description, err?.name, err?.httpCode, err?.statusCode].filter(Boolean).join(' ');
const s = String(msg || '').toLowerCase();
let code = 'GEMINI_UPSTREAM_ERROR';
let explanation = 'Gemini synthesis failed after automatic retries. No report was fabricated.';
let remedy = 'Open the failed Gemini HTTP node in n8n execution details; check the model endpoint, credential, and current API status.';
if (/401|unauthori[sz]|invalid.{0,12}(api )?key|credential/.test(s)) { code = 'GEMINI_AUTH_ERROR'; explanation = 'Gemini API authentication failed.'; remedy = 'Edit the Gemini Header Auth credential: header name x-goog-api-key, value your Google AI Studio API key. Then run again.'; }
else if (/403|forbidden|permission|not allowed/.test(s)) { code = 'GEMINI_ACCESS_ERROR'; explanation = 'Gemini rejected this model/API access.'; remedy = 'Confirm model availability for your project and verify the API key has Gemini Developer API access.'; }
else if (/429|quota|rate.?limit|resource exhausted|too many requests/.test(s)) { code = 'GEMINI_RATE_LIMIT'; explanation = 'Gemini rate/quota limit was reached. Retrying cannot clear exhausted free-tier quota.'; remedy = 'Wait for the rate-limit window or daily quota to reset, inspect Google AI Studio usage, then resubmit.'; }
else if (/timeout|timed out|etimedout|econnabort/.test(s)) { code = 'GEMINI_TIMEOUT'; explanation = 'Gemini did not respond before the request timeout.'; remedy = 'Check connectivity and provider status, then resubmit. Automatic transient retries have already been attempted.'; }
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeWorkMs = (Number(base.activeWorkMs) || 0) + (Date.now() - t0);
const wallClockMs = Date.now() - Number(base.wallStartMs || t0);
const html = `<main style="font-family:system-ui,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#222"><h1>Research synthesis failed</h1><p>${esc(explanation)}</p><p>${esc(remedy)}</p><p>Search evidence was retrieved, but the system will not present a report as complete without successful synthesis.</p><hr><p><b>Status:</b> ${esc(code)}</p><p><b>Topic:</b> ${esc(base.topic)}</p><p><b>Sources retrieved:</b> ${esc(base.sourceCount)}</p><p><b>Run ID:</b> ${esc(base.runId)}</p><p><b>Instrumented Code-node work:</b> ${activeWorkMs} ms</p><p><b>Elapsed:</b> ${wallClockMs} ms</p></main>`;
return [{json:{status:code,html,runId:base.runId,activeWorkMs,wallClockMs,sourceCount:base.sourceCount}}];
